import{_ as t,a,o,a4 as r}from"./chunks/framework.-FZumj2l.js";const u=JSON.parse('{"title":"MCP Server","description":"","frontmatter":{"outline":false},"headers":[],"relativePath":"api/build-with-ai/mcp-server.md","filePath":"api/build-with-ai/mcp-server.md","lastUpdated":1784902076000}'),n={name:"api/build-with-ai/mcp-server.md"};function s(i,e,d,l,h,c){return o(),a("div",null,e[0]||(e[0]=[r('<h1 id="mcp-server" tabindex="-1">MCP Server <a class="header-anchor" href="#mcp-server" aria-label="Permalink to &quot;MCP Server&quot;">​</a></h1><p>Bagisto provides an <strong>optional</strong> <a href="https://modelcontextprotocol.io" target="_blank" rel="noreferrer">MCP</a> (Model Context Protocol) server that lets an AI agent search this documentation on demand, from inside the editor, while it writes code.</p><p>It is optional: <a href="/llms.txt"><code>/llms.txt</code></a> and <a href="/llms-full.txt"><code>/llms-full.txt</code></a> cover the same knowledge statically. The MCP server is worth adding when you want the agent to pull the <em>exact</em> current page for an endpoint mid-task instead of ingesting the whole index.</p><h2 id="why-use-it" tabindex="-1">Why use it <a class="header-anchor" href="#why-use-it" aria-label="Permalink to &quot;Why use it&quot;">​</a></h2><ul><li><strong>Live lookup while coding.</strong> The agent fetches the precise request/response shape for an endpoint at the moment it needs it — no copy-pasting docs into the chat.</li><li><strong>Always current.</strong> It indexes the published docs, so the agent reads the same reference you do, not a stale snapshot from its training data.</li><li><strong>Smaller context.</strong> Instead of loading <code>llms-full.txt</code>, the agent pulls only the page it is working on, leaving room for your actual code.</li></ul><p>For building a storefront, that means when the agent reaches the checkout step it can look up the exact address-input fields and the shipping-then-payment sequence on demand, rather than guessing or asking you.</p><h2 id="tools-it-exposes" tabindex="-1">Tools it exposes <a class="header-anchor" href="#tools-it-exposes" aria-label="Permalink to &quot;Tools it exposes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Tool</th><th>What it does</th></tr></thead><tbody><tr><td><code>search_api_docs</code></td><td>Full-text search across the API documentation</td></tr><tr><td><code>list_endpoints</code></td><td>Enumerate documented endpoints (filterable by surface / menu)</td></tr><tr><td><code>get_doc</code></td><td>Fetch one page&#39;s full content by path</td></tr></tbody></table><h2 id="install" tabindex="-1">Install <a class="header-anchor" href="#install" aria-label="Permalink to &quot;Install&quot;">​</a></h2><ul><li><strong>Repository:</strong> <a href="https://github.com/bagisto/mcp" target="_blank" rel="noreferrer"><code>bagisto/mcp</code></a></li></ul><p>The repo README has the setup and the exact command to register the server with your agent (for example <code>claude mcp add</code> for Claude Code, or the editor&#39;s MCP settings for Cursor / Windsurf).</p><h2 id="do-you-need-it" tabindex="-1">Do you need it? <a class="header-anchor" href="#do-you-need-it" aria-label="Permalink to &quot;Do you need it?&quot;">​</a></h2><p>No — it is a convenience, not a requirement. If you have installed the <a href="/api/build-with-ai/agent-skills.html">Agent Skills</a> and the agent can reach <a href="/llms.txt"><code>/llms.txt</code></a>, you already have everything needed to build. Add the MCP server if you want on-demand, in-editor doc search on top of that.</p>',13)]))}const m=t(n,[["render",s]]);export{u as __pageData,m as default};
